static struct config *config_mock(char *key, char *value)
{
	char buf[CONFIG_MAX_KEY_LENGTH];
	struct config *config;
	int rc;

	config = malloc(sizeof(struct config));
	assert(config != NULL);

	config->dict = dictionary_new(1);
	assert(config->dict != NULL);

